export interface ResonanceInspiration {
  id: string;
  seed: number;
  lensKey: string;
  title: string;
  archetype: Archetype;
  paragraphs: [string, string];
  question: string;
  invitation: string;
}

export function seededRandom(seed: number) {
  let value = seed >>> 0;
  return () => {
    value += 0x6D2B79F5;
    let t = Math.imul(value ^ value >>> 15, 1 | value);
    t ^= t + Math.imul(t ^ t >>> 7, 61 | t);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

/** Un seul symbole. Les huit récits sont rencontrés avant un nouveau cycle. */
export function makeInspiration(archetype: Archetype, recent: string[], seed: number): ResonanceInspiration {
  if (!archetype?.id || !perspectives[archetype.id]) throw new Error('Choisir un symbole du disque.');
  const random = seededRandom(seed);
  const candidates = perspectives[archetype.id].map((lens, i) => ({ lens, key: `${archetype.id}-${i}` }));
  const keys = new Set(candidates.map(item => item.key));
  const history = recent.filter(key => keys.has(key));
  const cycleLength = history.length % candidates.length;
  const used = new Set(cycleLength ? history.slice(-cycleLength) : []);
  const unseen = candidates.filter(item => !used.has(item.key));
  const fresh = unseen.filter(item => !history.slice(-3).includes(item.key));
  const available = fresh.length ? fresh : unseen;
  const picked = available[Math.floor(random() * available.length)];
  return {
    id: `${seed}-${picked.key}`, seed, lensKey: picked.key, title: picked.lens.title, archetype,
    paragraphs: [picked.lens.opening, picked.lens.unfolding],
    question: picked.lens.questions[Math.floor(random() * 2)],
    invitation: picked.lens.invitation,
  };
}
